head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.gPageSize = 10; // 페이지 size
scwin.vCurrPageNo = 0; // 현재 선택된 페이지번호
scwin.gLastJob = "조회";
// 화면 리사이징

scwin.gAcptNo;
scwin.gIsurCd;
scwin.gDate;
scwin.gDepCd;
scwin.gEmpNo;
scwin.gLdMktTp;

// ********************************************************************
// [WebSquare 전환 추가] 원본 소스와 비교 필요
//
// ********************************************************************

scwin.gLdMktTp = js_market;
X < !불성실지정예고--;
클릭-- > function() {
    /*
            // 일자 체크
    		if( getObjectValue(edt_ToDate).length < 8) {
    			alert("일자 올바르게 입력하십시오." );
    			edt_ToDate.focus();
    			return;
    		}
     */
    fn_Search();
} < !불성실지정--;
클릭-- > function() {
    scwin.vCurrPageNo = 0;
    txb_TotalCnt.setValue("총건수 : ");
    const url_list = "/UnfaithfulDesign.do?method=listUnfaithfulKosdaq&inputMessageId=NFAITHKOSDAQCOND_IN" + "&outputMessageId=NFAITHKOSDAQLIST_OUT";
    const url_cond = "&FROM_DATE=" + "20130729" + "&TO_DATE=" + "99991231" + "&LIST_STAT=1" + "&LIMIT_ISU_YN=Y" + "&LD_MKT_TP=" + scwin.gLdMktTp + "&PAGENO=" + scwin.vCurrPageNo + "&PAGESIZE=" + scwin.gPageSize + "&SCREN_ID=" + 'ULDSTF35115.xml' + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;

    // 그리드의 데이타 조회
    dts_nfaith_list.DataID = encodeURI(url_list + url_cond);
    dts_nfaith_list.reset();
};

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        // fn_SetCode();
        fn_CheckCond();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35115.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description grd_Grid 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    try {
        // 클릭된 값 변수에 셋팅
        scwin.setContnId(row);
        if (colid === "DESIGN_DD") {
            await $c.stf.openDisclViewer(scwin.gAcptNo, 'R');
        } else if (colid === "COM_ABBRV") {
            $c.stf.fn_PopupCorpInfo();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35115.grd_Grid_OnDblClick" });
    }
};

/**
 * @method
 * @name dts_nfaith_list_OnLoadError
 * @description dts_nfaith_list 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_nfaith_list_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_nfaith_list);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35115.dts_nfaith_list_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_nfaith_list_OnLoadCompleted
 * @description dts_nfaith_list 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_nfaith_list_OnLoadCompleted = async function(rowcount) {
    try {
        if (dts_nfaith_list.errorMsg) {
            await $c.win.alert(dts_nfaith_list.errorMsg);
        } else {
            txb_TotalCnt.setValue("총건수 : " + rowcount);
            // alert(txb_TotalCnt.value );

        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35115.dts_nfaith_list_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name grd_Grid_OnClick
 * @description grd_Grid 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnClick = async function(row, colid) {
    try {
        await scwin.insert(grd_Grid, row, colid);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35115.grd_Grid_OnClick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name insert
 * @description insert 처리
 * @param {String} GridID GridID
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.insert = async function(GridID, row, colid) {
    const objDataID = document.all(GridID.DataID); // 가져오는 방식이 좀 특이하다..
    if (colid === "SEL_FUNC") {
        const res = window.confirm("추가 하시겠습니까?");
        if (res) {
            let lmtDd = "";
            scwin.gLastJob = "추가";
            if (objDataID.getCellData(row, "ACNTCLS_MMDD1") === "Y") {
                lmtDd = parseInt((objDataID.getCellData(row, "DESIGN_DD")).substr(0, 4)) + parseInt(1);
                lmtDd = lmtDd + "1231";
            } else {
                lmtDd = "";
            }
            url += "&REG_EMP_NO=" + js_emp_no;
            url += "&ACPT_NO=" + objDataID.getCellData(row, "ACPT_NO");
            url += "&ISUR_CD=" + objDataID.getCellData(row, "ISUR_CD");
            url += "&PRFM_FC_DISCLS_VIOL_YN=Y";
            url += "&DISCLS_SUBMIT_LMT_DD=" + lmtDd;
            const sbmOptions = {
                id : "sbm_dts_nfaith_list",
                action : "/UnfaithfulDesign.do",
                ref : "",
                target : "dts_nfaith_list=body.content",
                isProcessMsg : false
            };

            const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
            // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

            opener.fn_CheckCond();
            await $c.win.closePopup();
        }
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setContnId
 * @description 그리드에서 클릭 row의 변수셋팅
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setContnId = function(obj) {
    scwin.gAcptNo = dts_nfaith_list.getCellData(Number(obj), "ACPT_NO");
    scwin.gIsurCd = dts_nfaith_list.getCellData(Number(obj), "ISUR_CD");
    // alert("부모창:"+gAcptNo+","+gMainFormCd+","+ gFormVer+","+ gIsurCd);

};
